import React, { useState, useEffect } from 'react';
import { Card, Table, Tag, Button, Space, Modal, message, Input, Form, Popconfirm, Alert } from 'antd';
import { SearchOutlined, ReloadOutlined, EyeOutlined, InboxOutlined, WarningOutlined } from '@ant-design/icons';
import { API_BASE_URL } from '../../../utils/api';
import styles from './ContactMessages.module.css';

const ContactMessages = () => {
  const [messages, setMessages] = useState([]);
  const [filteredMessages, setFilteredMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [selectedMessage, setSelectedMessage] = useState(null);
  const [searchKeyword, setSearchKeyword] = useState('');
  const [messageType, setMessageType] = useState('active'); // 'active' 或 'archived'
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchMessages();
  }, [messageType]);

  useEffect(() => {
    if (searchKeyword) {
      const filtered = messages.filter(
        msg => 
          msg.attributes.name?.toLowerCase().includes(searchKeyword.toLowerCase()) ||
          msg.attributes.email?.toLowerCase().includes(searchKeyword.toLowerCase()) ||
          msg.attributes.message?.toLowerCase().includes(searchKeyword.toLowerCase())
      );
      setFilteredMessages(filtered);
    } else {
      setFilteredMessages(messages);
    }
  }, [messages, searchKeyword]);

  const fetchMessages = async () => {
    setLoading(true);
    setError(null);
    try {
      let queryString = `?sort=createdAt:desc&populate=*`;
      
      // 我們不改變schema，但可以利用publishedAt來實現封存功能
      // 當消息被封存時，我們設置publishedAt為null（草稿狀態）
      if (messageType === 'active') {
        queryString += `&publicationState=live`;
      } else {
        queryString += `&publicationState=preview`;
      }
      
      const response = await fetch(`${API_BASE_URL}/api/contact-messages${queryString}`);
      
      // 檢查是否獲取成功
      if (!response.ok) {
        if (response.status === 401 || response.status === 403) {
          throw new Error(`權限錯誤 (${response.status}): 請確認您有權限查看聯絡訊息。可能需要在Strapi中為您的角色開啟權限。`);
        }
        throw new Error(`API請求失敗: ${response.status} ${response.statusText}`);
      }
      
      const data = await response.json();
      
      // 對於歸檔訊息，我們只顯示publishedAt為null的項目
      let resultData = data.data || [];
      if (messageType === 'archived') {
        resultData = resultData.filter(item => item.attributes.publishedAt === null);
      }
      
      setMessages(resultData);
      setFilteredMessages(resultData);
    } catch (error) {
      console.error('Error fetching contact messages:', error);
      setError(error.message || '獲取聯絡訊息失敗');
      message.error('獲取聯絡訊息失敗: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleViewMessage = async (record) => {
    setSelectedMessage(record);
    setModalVisible(true);

    // 如果訊息未讀，標記為已讀
    if (record.attributes.status === 'new' || record.attributes.isRead === false) {
      try {
        const response = await fetch(`${API_BASE_URL}/api/contact-messages/${record.id}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            data: {
              status: 'read',
              isRead: true
            }
          }),
        });
        
        if (!response.ok) {
          throw new Error(`更新狀態失敗: ${response.status} ${response.statusText}`);
        }
        
        // 更新本地狀態
        const updatedMessages = messages.map(msg => 
          msg.id === record.id 
            ? {...msg, attributes: {...msg.attributes, status: 'read', isRead: true}} 
            : msg
        );
        setMessages(updatedMessages);
      } catch (error) {
        console.error('Error updating message status:', error);
        message.error('標記訊息為已讀失敗: ' + error.message);
      }
    }
  };

  const handleArchive = async (record) => {
    try {
      // 使用publishedAt來模擬封存（將消息設為草稿狀態）
      const response = await fetch(`${API_BASE_URL}/api/contact-messages/${record.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          data: {
            publishedAt: null
          }
        }),
      });
      
      if (!response.ok) {
        throw new Error(`封存失敗: ${response.status} ${response.statusText}`);
      }
      
      message.success('訊息已封存');
      fetchMessages();
    } catch (error) {
      console.error('Error archiving message:', error);
      message.error('封存訊息失敗: ' + error.message);
    }
  };

  const handleRestore = async (record) => {
    try {
      // 恢復訊息（將訊息發布）
      const currentTime = new Date().toISOString();
      const response = await fetch(`${API_BASE_URL}/api/contact-messages/${record.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          data: {
            publishedAt: currentTime
          }
        }),
      });
      
      if (!response.ok) {
        throw new Error(`恢復失敗: ${response.status} ${response.statusText}`);
      }
      
      message.success('訊息已恢復');
      fetchMessages();
    } catch (error) {
      console.error('Error restoring message:', error);
      message.error('恢復訊息失敗: ' + error.message);
    }
  };

  const handleSearch = (e) => {
    setSearchKeyword(e.target.value);
  };

  const columns = [
    {
      title: '姓名',
      dataIndex: ['attributes', 'name'],
      key: 'name',
    },
    {
      title: '電子郵件',
      dataIndex: ['attributes', 'email'],
      key: 'email',
    },
    {
      title: '電話',
      dataIndex: ['attributes', 'phone'],
      key: 'phone',
      render: (phone) => phone || '-',
    },
    {
      title: '訊息內容',
      dataIndex: ['attributes', 'message'],
      key: 'message',
      ellipsis: true,
      render: (text) => text?.substring(0, 50) + (text?.length > 50 ? '...' : '') || '-',
    },
    {
      title: '狀態',
      dataIndex: ['attributes', 'status'],
      key: 'status',
      render: (status, record) => {
        // 檢查status和isRead屬性
        const isUnread = status === 'new' || record.attributes.isRead === false;
        return (
          <Tag color={isUnread ? 'blue' : 'green'}>
            {isUnread ? '未讀' : '已讀'}
          </Tag>
        );
      },
    },
    {
      title: '提交時間',
      dataIndex: ['attributes', 'createdAt'],
      key: 'createdAt',
      render: (createdAt) => new Date(createdAt).toLocaleString(),
    },
    {
      title: '操作',
      key: 'action',
      render: (_, record) => (
        <Space>
          <Button 
            type="primary" 
            icon={<EyeOutlined />} 
            onClick={() => handleViewMessage(record)}
            size="small"
          >
            查看
          </Button>
          {messageType === 'active' ? (
            <Popconfirm
              title="確定要封存此訊息？"
              onConfirm={() => handleArchive(record)}
              okText="確定"
              cancelText="取消"
            >
              <Button 
                type="default" 
                icon={<InboxOutlined />} 
                size="small"
              >
                封存
              </Button>
            </Popconfirm>
          ) : (
            <Popconfirm
              title="確定要恢復此訊息？"
              onConfirm={() => handleRestore(record)}
              okText="確定"
              cancelText="取消"
            >
              <Button 
                type="default" 
                size="small"
              >
                恢復
              </Button>
            </Popconfirm>
          )}
        </Space>
      ),
    },
  ];

  return (
    <Card
      title="網站聯絡訊息"
      extra={
        <Space>
          <div className={styles.tabButtons}>
            <Button 
              type={messageType === 'active' ? 'primary' : 'default'}
              onClick={() => setMessageType('active')}
            >
              活躍訊息
            </Button>
            <Button 
              type={messageType === 'archived' ? 'primary' : 'default'}
              onClick={() => setMessageType('archived')}
            >
              已封存
            </Button>
          </div>
          <Input
            placeholder="搜索訊息"
            prefix={<SearchOutlined />}
            value={searchKeyword}
            onChange={handleSearch}
            style={{ width: 250 }}
          />
          <Button 
            icon={<ReloadOutlined />} 
            onClick={fetchMessages}
          >
            刷新
          </Button>
        </Space>
      }
    >
      {error && (
        <Alert
          message="錯誤"
          description={error}
          type="error"
          showIcon
          icon={<WarningOutlined />}
          style={{ marginBottom: 16 }}
          action={
            <Button size="small" danger onClick={fetchMessages}>
              重試
            </Button>
          }
        />
      )}
      
      <Table
        columns={columns}
        dataSource={filteredMessages}
        rowKey={(record) => record.id}
        loading={loading}
        locale={{
          emptyText: error ? '載入失敗' : (loading ? '載入中...' : '目前沒有聯絡訊息')
        }}
      />

      <Modal
        title="聯絡訊息詳情"
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        footer={[
          <Button key="close" onClick={() => setModalVisible(false)}>
            關閉
          </Button>
        ]}
        width={700}
      >
        {selectedMessage && (
          <Form layout="vertical">
            <Form.Item label="姓名">
              <Input value={selectedMessage.attributes.name} readOnly />
            </Form.Item>
            <Form.Item label="電子郵件">
              <Input value={selectedMessage.attributes.email} readOnly />
            </Form.Item>
            <Form.Item label="電話">
              <Input value={selectedMessage.attributes.phone || '-'} readOnly />
            </Form.Item>
            <Form.Item label="訊息內容">
              <Input.TextArea 
                value={selectedMessage.attributes.message} 
                readOnly 
                rows={6}
              />
            </Form.Item>
            <Form.Item label="提交時間">
              <Input 
                value={new Date(selectedMessage.attributes.createdAt).toLocaleString()} 
                readOnly 
              />
            </Form.Item>
          </Form>
        )}
      </Modal>
    </Card>
  );
};

export default ContactMessages; 